pub struct StoragePinArgs {
    /// Path to the Norito-encoded manifest (`.to` file).
    #[arg(long, value_name = "PATH")]
    pub manifest: PathBuf,
    /// Path to the raw payload bytes referenced by the manifest.
    #[arg(long, value_name = "PATH")]
    pub payload: PathBuf,
}

impl Run for StoragePinArgs {
    fn run<C: RunContext>(self, context: &mut C) -> Result<()> {
        self.run_with(context, |client, manifest, payload, files| {
            client.post_sorafs_storage_pin(manifest, payload, files)
        })
    }
}

impl StoragePinArgs {
    fn run_with<C, F>(&self, context: &mut C, submit: F) -> Result<()>
    where
        C: RunContext,
        F: FnOnce(
            &Client,
            &[u8],
            &[u8],
            Option<&[iroha::client::SorafsStorageFileEntry<'_>]>,
        ) -> Result<Response<Vec<u8>>>,
    {
        let manifest_bytes = fs::read(&self.manifest).wrap_err("failed to read manifest file")?;
        let (payload_bytes, files) = load_storage_pin_payload(&self.payload, &manifest_bytes)?;
        let borrowed_files = files.as_ref().map(|entries| {
            entries
                .iter()
                .map(|entry| iroha::client::SorafsStorageFileEntry {
                    path: entry.path.as_slice(),
                    size: entry.size,
                })
                .collect::<Vec<_>>()
        });

        let client = context.client_from_config();
        let response = submit(
            &client,
            &manifest_bytes,
            &payload_bytes,
            borrowed_files.as_deref(),
        )?;
        let status = response.status();
        let body = response.into_body();
        match status {
            StatusCode::OK => render_json_body(context, &body),
            status => Err(make_http_error(status, &body)),
        }
    }
}

#[derive(Debug, Clone)]
struct OwnedStorageFileEntry {
    path: Vec<String>,
    size: u64,
}

fn load_storage_pin_payload(
    input: &Path,
    manifest_bytes: &[u8],
) -> Result<(Vec<u8>, Option<Vec<OwnedStorageFileEntry>>)> {
    let metadata = fs::metadata(input)
        .wrap_err_with(|| format!("failed to access payload `{}`", input.display()))?;

    if metadata.is_dir() {
        let manifest: ManifestV1 = norito::decode_from_bytes(manifest_bytes)
            .wrap_err("failed to decode manifest payload")?;
        let profile = chunk_profile_from_manifest(&manifest)?;
        let (plan, payload) = CarBuildPlan::from_directory_with_profile(input, profile)
            .map_err(|err| eyre!("failed to build directory payload plan: {err}"))?;
        let files = plan
            .files
            .iter()
            .map(|file| OwnedStorageFileEntry {
                path: file.path.clone(),
                size: file.size,
            })
            .collect();
        return Ok((payload, Some(files)));
    }

    if metadata.is_file() {
        let payload = fs::read(input)
            .wrap_err_with(|| format!("failed to read payload file `{}`", input.display()))?;
        return Ok((payload, None));
    }

    Err(eyre!("payload input must be a file or directory"))
}

fn chunk_profile_from_manifest(manifest: &ManifestV1) -> Result<ChunkProfile> {
    Ok(ChunkProfile {
        min_size: usize::try_from(manifest.chunking.min_size)
            .wrap_err("manifest chunking.min_size exceeds host limits")?,
        target_size: usize::try_from(manifest.chunking.target_size)
            .wrap_err("manifest chunking.target_size exceeds host limits")?,
        max_size: usize::try_from(manifest.chunking.max_size)
            .wrap_err("manifest chunking.max_size exceeds host limits")?,
        break_mask: u64::from(manifest.chunking.break_mask),
    })
}

#[derive(clap::Subcommand, Debug)]
pub enum StorageTokenCommand {
    /// Issue a stream token for a manifest/provider pair.
    Issue(StorageTokenIssueArgs),
}

impl Run for StorageTokenCommand {
    fn run<C: RunContext>(self, context: &mut C) -> Result<()> {
        match self {
            StorageTokenCommand::Issue(args) => args.run(context),
        }
    }
}

#[derive(clap::Args, Debug)]
pub struct StorageTokenIssueArgs {
    /// Hex-encoded manifest identifier stored on the gateway.
    #[arg(long, value_name = "HEX")]
    pub manifest_id: String,
    /// Hex-encoded provider identifier authorised to serve the manifest.
    #[arg(long, value_name = "HEX")]
    pub provider_id: String,
    /// Logical client identifier used for quota accounting.
    #[arg(long, value_name = "STRING")]
    pub client_id: String,
    /// Optional nonce to send in the request headers (auto-generated when omitted).
    #[arg(long, value_name = "STRING")]
    pub nonce: Option<String>,
    /// Override the default TTL expressed in seconds.
    #[arg(long, value_name = "SECONDS")]
    pub ttl_secs: Option<u64>,
    /// Override the maximum concurrent stream count.
    #[arg(long, value_name = "COUNT")]
    pub max_streams: Option<u16>,
    /// Override the sustained throughput limit in bytes per second.
    #[arg(long, value_name = "BYTES")]
    pub rate_limit_bytes: Option<u64>,
    /// Override the allowed number of refresh requests per minute.
    #[arg(long, value_name = "COUNT")]
    pub requests_per_minute: Option<u32>,
}

impl Run for StorageTokenIssueArgs {
    fn run<C: RunContext>(self, context: &mut C) -> Result<()> {
        self.run_with(
            context,
            |client, manifest, provider, client_id, nonce, overrides| {
                client.post_sorafs_storage_token(manifest, provider, client_id, nonce, overrides)
            },
        )
    }
}

impl StorageTokenIssueArgs {
    fn run_with<C, F>(&self, context: &mut C, issue: F) -> Result<()>
    where
        C: RunContext,
        F: FnOnce(
            &Client,
            &str,
            &str,
            &str,
            &str,
            &SorafsTokenOverrides,
        ) -> Result<Response<Vec<u8>>>,
    {
        let nonce = match self.nonce.clone() {
            Some(nonce) => nonce,
            None => generate_nonce_hex(12)?,
        };
        let overrides = SorafsTokenOverrides {
            ttl_secs: self.ttl_secs,
            max_streams: self.max_streams,
            rate_limit_bytes: self.rate_limit_bytes,
            requests_per_minute: self.requests_per_minute,
        };

        let client = context.client_from_config();
        let response = issue(
            &client,
            &self.manifest_id,
            &self.provider_id,
            &self.client_id,
            &nonce,
            &overrides,
        )?;

        if self.nonce.is_none() && response.status().is_success() {
            context.println(format!("nonce: {nonce}"))?;
        }

        render_json_response(context, response)
    }
}

fn parse_timestamp(raw: Option<&str>, field: &str) -> Result<Option<OffsetDateTime>> {
    let Some(value) = raw else {
        return Ok(None);
    };
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Err(eyre!("`{field}` must not be empty when provided"));
    }
    let parsed =
        OffsetDateTime::parse(trimmed, &Rfc3339).wrap_err_with(|| format!("invalid `{field}`"))?;
    Ok(Some(parsed))
}

fn ensure_optional_non_empty(field: Option<&str>, name: &str) -> Result<()> {
    if let Some(value) = field
        && value.trim().is_empty()
    {
        return Err(eyre!("`{name}` must not be empty when provided"));
    }
    Ok(())
}

fn duration_to_time_delta(delta: Duration, label: &str) -> Result<TimeDelta> {
    let seconds = i64::try_from(delta.as_secs())
        .map_err(|_| eyre!("{label} exceeds supported duration range"))?;
    let nanos = delta.subsec_nanos();
    TimeDelta::seconds(seconds)
        .checked_add(TimeDelta::nanoseconds(i64::from(nanos)))
        .ok_or_else(|| eyre!("{label} overflowed while converting duration"))
}

fn add_datetime_duration(
    base: OffsetDateTime,
    delta: Duration,
    label: &str,
) -> Result<OffsetDateTime> {
    let step = duration_to_time_delta(delta, label)?;
    base.checked_add(step)
        .ok_or_else(|| eyre!("{label} overflowed while validating gateway denylist policy"))
}

fn format_datetime(value: OffsetDateTime) -> String {
    value
        .format(&Rfc3339)
        .expect("RFC3339 formatting should be infallible")
}

#[derive(Debug)]
struct ModerationOperatorCanaryHttpResponse {
    status: StatusCode,
    content_type: Option<String>,
    body: Vec<u8>,
}

#[derive(Clone)]
struct ModerationOperatorCanaryRouteSpec {
    name: &'static str,
    path: String,
    expected_schema: Option<&'static str>,
    expect_html_marker: Option<&'static str>,
    include_limit: bool,
}

fn moderation_operator_canary_http_get(
    client: &BlockingHttpClient,
    url: &str,
) -> Result<ModerationOperatorCanaryHttpResponse> {
    let response = client.get(url).send().wrap_err_with(|| {
        format!("failed to GET SoraFS moderation operator canary route `{url}`")
    })?;
    let status = StatusCode::from_u16(response.status().as_u16()).map_err(|err| {
        eyre!("SoraFS moderation operator canary route `{url}` returned unsupported status: {err}")
    })?;
    let content_type = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(ToOwned::to_owned);
    let body = response
        .bytes()
        .wrap_err_with(|| {
            format!("failed to read SoraFS moderation operator canary route `{url}` body")
        })?
        .to_vec();
    Ok(ModerationOperatorCanaryHttpResponse {
        status,
        content_type,
        body,
    })
}

