struct ModerationOperatorBallotTallyReference {
    case_id: String,
    round_id: String,
}

impl ModerationOperatorBallotTallyReference {
    fn as_request(&self) -> SorafsModerationBallotTallyRequest<'_> {
        SorafsModerationBallotTallyRequest {
            case_id: self.case_id.as_str(),
            round_id: self.round_id.as_str(),
        }
    }
}

fn moderation_operator_ballot_tally_payload_from_body(
    body: &[u8],
) -> Result<Option<ModerationOperatorBallotTallyReference>, ModerationOperatorRequestError> {
    let value = moderation_operator_payload_free_json_value(body, "ballot-tally request")?;
    let fields = value_object(&value, "ballot-tally request").map_err(|err| {
        ModerationOperatorRequestError::new(StatusCode::BAD_REQUEST, err.to_string())
    })?;
    let case_id = optional_json_text(fields, "case_id").map_err(|err| {
        ModerationOperatorRequestError::new(StatusCode::BAD_REQUEST, err.to_string())
    })?;
    let round_id = optional_json_text(fields, "round_id").map_err(|err| {
        ModerationOperatorRequestError::new(StatusCode::BAD_REQUEST, err.to_string())
    })?;
    match (case_id, round_id) {
        (Some(case_id), Some(round_id)) => Ok(Some(ModerationOperatorBallotTallyReference {
            case_id,
            round_id,
        })),
        (None, None) => Ok(None),
        _ => Err(ModerationOperatorRequestError::new(
            StatusCode::BAD_REQUEST,
            "ballot-tally request must provide both case_id and round_id, or neither",
        )),
    }
}

fn moderation_operator_ballot_tally_reference_from_panel(
    panel: &Value,
) -> Result<ModerationOperatorBallotTallyReference> {
    let root = value_object(panel, "operator panel response")?;
    let schema = required_string_field(root, "schema", "operator panel response")?;
    if schema != "sorafs.moderation.quarantine.operator_panel.v1" {
        return Err(eyre!(
            "operator panel response schema `{schema}` is not supported by ballot-tally"
        ));
    }
    let ballots = root
        .get("ballots")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    let Some((case_id, round_id)) = first_moderation_ballot_reference(ballots) else {
        return Err(eyre!(
            "operator panel response does not include a moderation ballot reference"
        ));
    };
    Ok(ModerationOperatorBallotTallyReference {
        case_id: required_trimmed_text(case_id, "case_id")?,
        round_id: required_trimmed_text(round_id, "round_id")?,
    })
}

fn moderation_operator_payload_free_json_body(
    body: &[u8],
    label: &str,
) -> Result<Vec<u8>, ModerationOperatorRequestError> {
    let value = moderation_operator_payload_free_json_value(body, label)?;
    norito::json::to_vec(&value).map_err(|err| {
        ModerationOperatorRequestError::new(
            StatusCode::BAD_REQUEST,
            format!("failed to canonicalize SoraFS moderation operator service {label}: {err}"),
        )
    })
}

fn moderation_operator_payload_free_json_value(
    body: &[u8],
    label: &str,
) -> Result<Value, ModerationOperatorRequestError> {
    let value: Value = norito::json::from_slice(body).map_err(|err| {
        ModerationOperatorRequestError::new(
            StatusCode::BAD_REQUEST,
            format!("failed to parse SoraFS moderation operator service {label} JSON: {err}"),
        )
    })?;
    ensure_moderation_bridge_plan_has_no_payload(&value).map_err(|err| {
        ModerationOperatorRequestError::new(StatusCode::BAD_REQUEST, err.to_string())
    })?;
    Ok(value)
}

fn moderation_operator_success_json_response(
    response: Response<Vec<u8>>,
    operation: &str,
) -> ModerationOperatorHttpResponse {
    let status = response.status();
    let body = response.into_body();
    if !matches!(status, StatusCode::OK | StatusCode::ACCEPTED) {
        return moderation_operator_upstream_response(status, body);
    }
    match moderation_operator_payload_free_json_value(&body, operation) {
        Ok(value) => moderation_operator_json_response(status, &value),
        Err(err) => moderation_operator_json_error(
            StatusCode::BAD_GATEWAY,
            format!(
                "unsafe or invalid {operation} response from Torii: {}",
                err.message
            ),
        ),
    }
}

fn moderation_operator_upstream_response(
    status: StatusCode,
    body: Vec<u8>,
) -> ModerationOperatorHttpResponse {
    if body.is_empty() {
        moderation_operator_json_error(status, format!("Torii returned status {status}"))
    } else {
        ModerationOperatorHttpResponse {
            status,
            content_type: ModerationOperatorService::JSON_CONTENT_TYPE,
            body,
        }
    }
}

fn moderation_operator_json_response(
    status: StatusCode,
    value: &Value,
) -> ModerationOperatorHttpResponse {
    let body = norito::json::to_vec(value).unwrap_or_else(|_| {
        br#"{"schema":"sorafs.moderation.quarantine.operator_service.error.v1","error":"failed to encode SoraFS moderation operator service JSON"}"#.to_vec()
    });
    ModerationOperatorHttpResponse {
        status,
        content_type: ModerationOperatorService::JSON_CONTENT_TYPE,
        body,
    }
}

fn moderation_operator_json_error(
    status: StatusCode,
    message: impl Into<String>,
) -> ModerationOperatorHttpResponse {
    let message = message.into();
    moderation_operator_json_response(
        status,
        &norito::json!({
            "schema": "sorafs.moderation.quarantine.operator_service.error.v1",
            "error": (message)
        }),
    )
}

fn moderation_operator_status_reason(status: StatusCode) -> &'static str {
    match status {
        StatusCode::OK => "OK",
        StatusCode::ACCEPTED => "Accepted",
        StatusCode::BAD_REQUEST => "Bad Request",
        StatusCode::UNAUTHORIZED => "Unauthorized",
        StatusCode::FORBIDDEN => "Forbidden",
        StatusCode::NOT_FOUND => "Not Found",
        StatusCode::METHOD_NOT_ALLOWED => "Method Not Allowed",
        StatusCode::PAYLOAD_TOO_LARGE => "Payload Too Large",
        StatusCode::BAD_GATEWAY => "Bad Gateway",
        StatusCode::INTERNAL_SERVER_ERROR => "Internal Server Error",
        _ => "Status",
    }
}

fn normalize_hex_32_lower(value: &str, flag: &str) -> Result<String> {
    let trimmed = required_trimmed_text(value, flag)?;
    let hex_value = trimmed.strip_prefix("0x").unwrap_or(&trimmed);
    let bytes =
        decode(hex_value).wrap_err_with(|| format!("{flag} must be a 32-byte hex string"))?;
    if bytes.len() != 32 {
        return Err(eyre!("{flag} must be a 32-byte hex string"));
    }
    Ok(encode(bytes))
}

fn build_reserve_movement_request_value<C: RunContext>(
    context: &C,
    args: &ReserveMovementSubmitArgs,
) -> Result<Value> {
    let provider_id_hex = normalize_hex_32_lower(&args.provider_id_hex, "--provider-id-hex")?;
    let provider_account = crate::resolve_account_id(context, &args.provider_account)
        .wrap_err("failed to resolve --provider-account")?;
    let reserve_account = crate::resolve_account_id(context, &args.reserve_account)
        .wrap_err("failed to resolve --reserve-account")?;
    let asset_definition = AssetDefinitionId::parse_address_literal(&args.asset_definition)
        .wrap_err("failed to parse --asset-definition")?;
    let amount = parse_xor_amount_decimal_labeled(&args.amount, "reserve movement amount")?;
    if amount.is_zero() {
        return Err(eyre!("reserve movement amount must be greater than zero"));
    }
    let idempotency_key = required_trimmed_text(&args.idempotency_key, "--idempotency-key")?;

    let mut root = Map::new();
    root.insert("provider_id_hex".into(), Value::from(provider_id_hex));
    root.insert(
        "provider_account".into(),
        Value::from(provider_account.to_string()),
    );
    root.insert(
        "reserve_account".into(),
        Value::from(reserve_account.to_string()),
    );
    root.insert(
        "asset_definition_id".into(),
        Value::from(asset_definition.to_string()),
    );
    root.insert(
        "amount_micro_xor".into(),
        Value::from(amount.as_micro().to_string()),
    );
    root.insert("idempotency_key".into(), Value::from(idempotency_key));
    root.insert(
        "observed_at_unix".into(),
        args.observed_at_unix.map_or(Value::Null, Value::from),
    );
    Ok(Value::Object(root))
}

fn build_reserve_movement_custody_value(args: &ReserveCustodyArgs) -> Result<(String, Value)> {
    let movement_id_hex = normalize_hex_32_lower(&args.movement_id_hex, "--movement-id-hex")?;
    let tx_hash_hex = normalize_hex_32_lower(&args.tx_hash_hex, "--tx-hash-hex")?;
    let mut root = Map::new();
    root.insert("status".into(), Value::from(args.status.label()));
    root.insert("tx_hash_hex".into(), Value::from(tx_hash_hex));
    root.insert(
        "observed_at_unix".into(),
        args.observed_at_unix.map_or(Value::Null, Value::from),
    );
    Ok((movement_id_hex, Value::Object(root)))
}

fn build_reserve_appeal_request_value<C: RunContext>(
    context: &C,
    args: &ReserveAppealSubmitArgs,
) -> Result<Value> {
    let provider_id_hex = normalize_hex_32_lower(&args.provider_id_hex, "--provider-id-hex")?;
    let provider_account = crate::resolve_account_id(context, &args.provider_account)
        .wrap_err("failed to resolve --provider-account")?;
    let reason = required_trimmed_text(&args.reason, "--reason")?;
    let idempotency_key = required_trimmed_text(&args.idempotency_key, "--idempotency-key")?;
    let evidence_digest_hex = args
        .evidence_digest_hex
        .as_deref()
        .map(|digest| normalize_hex_32_lower(digest, "--evidence-digest-hex"))
        .transpose()?;

    let mut root = Map::new();
    root.insert("provider_id_hex".into(), Value::from(provider_id_hex));
    root.insert(
        "provider_account".into(),
        Value::from(provider_account.to_string()),
    );
    root.insert(
        "requested_stage".into(),
        args.requested_stage
            .map_or(Value::Null, |stage| Value::from(stage.label())),
    );
    root.insert("reason".into(), Value::from(reason));
    root.insert(
        "evidence_digest_hex".into(),
        evidence_digest_hex.map_or(Value::Null, Value::from),
    );
    root.insert("idempotency_key".into(), Value::from(idempotency_key));
    root.insert(
        "observed_at_unix".into(),
        args.observed_at_unix.map_or(Value::Null, Value::from),
    );
    Ok(Value::Object(root))
}

fn build_reserve_appeal_decision_value<C: RunContext>(
    context: &C,
    args: &ReserveAppealDecideArgs,
) -> Result<(String, Value)> {
    let appeal_id_hex = normalize_hex_32_lower(&args.appeal_id_hex, "--appeal-id-hex")?;
    let decision_account = crate::resolve_account_id(context, &args.decision_account)
        .wrap_err("failed to resolve --decision-account")?;
    let rationale = required_trimmed_text(&args.rationale, "--rationale")?;
    let mut root = Map::new();
    root.insert("status".into(), Value::from(args.status.label()));
    root.insert(
        "decision_account".into(),
        Value::from(decision_account.to_string()),
    );
    root.insert("rationale".into(), Value::from(rationale));
    root.insert(
        "observed_at_unix".into(),
        args.observed_at_unix.map_or(Value::Null, Value::from),
    );
    Ok((appeal_id_hex, Value::Object(root)))
}

fn build_reserve_lifecycle_policy_value<C: RunContext>(
    context: &C,
    args: &ReservePolicyUpdateArgs,
) -> Result<Value> {
    if args.grace_period_days >= args.default_after_days {
        return Err(eyre!(
            "--grace-days must be lower than --default-after-days for reserve lifecycle policy"
        ));
    }
    let authority_account = crate::resolve_account_id(context, &args.authority_account)
        .wrap_err("failed to resolve --authority-account")?;
    let reason = required_trimmed_text(&args.reason, "--reason")?;
    let idempotency_key = required_trimmed_text(&args.idempotency_key, "--idempotency-key")?;
    let mut root = Map::new();
    root.insert(
        "authority_account".into(),
        Value::from(authority_account.to_string()),
    );
    root.insert(
        "grace_period_days".into(),
        Value::from(u64::from(args.grace_period_days)),
    );
    root.insert(
        "default_after_days".into(),
        Value::from(u64::from(args.default_after_days)),
    );
    root.insert(
        "effective_at_unix".into(),
        Value::from(args.effective_at_unix),
    );
    root.insert("reason".into(), Value::from(reason));
    root.insert("idempotency_key".into(), Value::from(idempotency_key));
    root.insert(
        "observed_at_unix".into(),
        args.observed_at_unix.map_or(Value::Null, Value::from),
    );
    Ok(Value::Object(root))
}

fn parse_xor_amount_decimal(input: &str) -> Result<XorAmount> {
    parse_xor_amount_decimal_labeled(input, "reserve balance")
}

fn parse_xor_amount_decimal_labeled(input: &str, label: &str) -> Result<XorAmount> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(eyre!("{label} must not be empty"));
    }
    if trimmed.starts_with('-') {
        return Err(eyre!("{label} must be non-negative"));
    }
    let mut parts = trimmed.split('.');
    let whole_part = parts.next().unwrap_or("");
    let fractional_part = parts.next().unwrap_or("");
    if parts.next().is_some() {
        return Err(eyre!("{label} may contain at most one decimal separator"));
    }
    if whole_part.is_empty() && fractional_part.is_empty() {
        return Err(eyre!("{label} must contain digits"));
    }
    if !whole_part.chars().all(|c| c.is_ascii_digit()) {
        return Err(eyre!("{label} contains invalid characters"));
    }
    if !fractional_part.chars().all(|c| c.is_ascii_digit()) {
        return Err(eyre!("{label} fractional part is invalid"));
    }
    if fractional_part.len() > 6 {
        return Err(eyre!(
            "{label} supports up to six fractional digits (micro XOR precision)"
        ));
    }
    let whole_value = if whole_part.is_empty() {
        0
    } else {
        whole_part
            .parse::<u128>()
            .wrap_err("failed to parse whole-number component")?
    };
    let mut fractional_value = 0u128;
    let mut digits = 0;
    for ch in fractional_part.chars() {
        digits += 1;
        fractional_value = fractional_value * 10 + u128::from(ch as u8 - b'0');
    }
    if digits > 0 {
        for _ in digits..6 {
            fractional_value *= 10;
        }
    }
    let base = whole_value
        .checked_mul(MICRO_XOR_PER_XOR)
        .ok_or_else(|| eyre!("{label} exceeds supported range"))?;
    let total = base
        .checked_add(fractional_value)
        .ok_or_else(|| eyre!("{label} exceeds supported range"))?;
    Ok(XorAmount::from_micro(total))
}

fn load_reserve_policy_from_paths(
    json_path: Option<&Path>,
    norito_path: Option<&Path>,
) -> Result<(ReservePolicyV1, String)> {
    match (json_path, norito_path) {
        (Some(_), Some(_)) => Err(eyre!(
            "only one of --policy-json or --policy-norito may be supplied"
        )),
        (Some(path), None) => {
            let contents = fs::read_to_string(path).wrap_err_with(|| {
                format!("failed to read reserve policy JSON `{}`", path.display())
            })?;
            let policy: ReservePolicyV1 = norito::json::from_str(&contents)
                .wrap_err("failed to parse reserve policy JSON")?;
            Ok((policy, format!("policy JSON `{}`", path.display())))
        }
        (None, Some(path)) => {
            let bytes = fs::read(path).wrap_err_with(|| {
                format!("failed to read reserve policy Norito `{}`", path.display())
            })?;
            let policy = decode_from_bytes::<ReservePolicyV1>(&bytes)
                .wrap_err("failed to decode reserve policy Norito bytes")?;
            Ok((policy, format!("policy Norito `{}`", path.display())))
        }
        (None, None) => Ok((
            ReservePolicyV1::default(),
            "embedded default policy".to_string(),
        )),
    }
}

#[allow(clippy::too_many_arguments)]
fn build_reserve_quote_value(
    policy: &ReservePolicyV1,
    storage_class: StorageClass,
    tier: ReserveTier,
    duration: ReserveDuration,
    capacity_gib: u64,
    reserve_balance: XorAmount,
    quote: &ReserveQuote,
    policy_source: &str,
) -> Result<Value> {
    let mut root = Map::new();
    root.insert(
        "policy_source".into(),
        Value::from(policy_source.to_string()),
    );

    let mut inputs = Map::new();
    inputs.insert(
        "storage_class".into(),
        Value::from(storage_class_label(storage_class)),
    );
    inputs.insert("tier".into(), Value::from(reserve_tier_label(tier)));
    inputs.insert(
        "duration".into(),
        Value::from(reserve_duration_label(duration)),
    );
    inputs.insert(
        "capacity_gib".into(),
        Value::Number(Number::from(capacity_gib)),
    );
    let reserve_value =
        norito::json::to_value(&reserve_balance).wrap_err("serialize reserve balance to JSON")?;
    inputs.insert("reserve_balance".into(), reserve_value);
    root.insert("inputs".into(), Value::Object(inputs));

    let policy_value =
        norito::json::to_value(policy).wrap_err("serialize reserve policy to JSON")?;
    root.insert("policy".into(), policy_value);
    let quote_value = norito::json::to_value(quote).wrap_err("serialize reserve quote to JSON")?;
    root.insert("quote".into(), quote_value);
    let projection_value = norito::json::to_value(&quote.ledger_projection())
        .wrap_err("serialize reserve ledger projection to JSON")?;
    root.insert("ledger_projection".into(), projection_value);

    Ok(Value::Object(root))
}

fn write_reserve_quote_artifact(path: &Path, value: &Value) -> Result<()> {
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        fs::create_dir_all(parent).wrap_err_with(|| {
            format!(
                "failed to create reserve quote artifact directory `{}`",
                parent.display()
            )
        })?;
    }
    let rendered =
        norito::json::to_json_pretty(value).wrap_err("failed to render reserve quote artifact")?;
    fs::write(path, rendered).wrap_err_with(|| {
        format!(
            "failed to write reserve quote artifact `{}`",
            path.display()
        )
    })
}

#[derive(Clone, Copy)]
struct LedgerProjectionAmounts {
    rent_due: XorAmount,
    reserve_shortfall: XorAmount,
    top_up_shortfall: XorAmount,
}

fn extract_ledger_projection(value: &Value) -> Result<LedgerProjectionAmounts> {
    let root = value
        .as_object()
        .ok_or_else(|| eyre!("reserve quote must be a JSON object"))?;
    let ledger_value = root
        .get("ledger_projection")
        .ok_or_else(|| eyre!("reserve quote missing `ledger_projection` block"))?;

    if let Some(ledger) = ledger_value.as_object() {
        let rent_due = parse_optional_micro_amount(ledger, "rent_due_micro_xor")?;
        let reserve_shortfall = parse_optional_micro_amount(ledger, "reserve_shortfall_micro_xor")?;
        let top_up_shortfall = parse_optional_micro_amount(ledger, "top_up_shortfall_micro_xor")?
            .unwrap_or_else(XorAmount::zero);

        if let (Some(rent_due), Some(reserve_shortfall)) = (rent_due, reserve_shortfall) {
            return Ok(LedgerProjectionAmounts {
                rent_due,
                reserve_shortfall,
                top_up_shortfall,
            });
        }
    }

    let projection: ReserveLedgerProjection = norito::json::from_value(ledger_value.clone())
        .wrap_err("failed to parse reserve ledger projection from quote")?;
    Ok(LedgerProjectionAmounts {
        rent_due: projection.rent_due,
        reserve_shortfall: projection.reserve_shortfall,
        top_up_shortfall: projection.top_up_shortfall,
    })
}

fn extract_reserve_quote(value: &Value) -> Result<ReserveQuote> {
    let root = value
        .as_object()
        .ok_or_else(|| eyre!("reserve quote must be a JSON object"))?;
    let quote_value = root
        .get("quote")
        .ok_or_else(|| eyre!("reserve quote missing `quote` block"))?;
    norito::json::from_value(quote_value.clone())
        .wrap_err("failed to parse reserve quote from quote artifact")
}

fn parse_optional_micro_amount(map: &Map, key: &str) -> Result<Option<XorAmount>> {
    map.get(key).map_or_else(
        || Ok(None),
        |value| {
            value_to_micro(value, key)
                .map(XorAmount::from_micro)
                .map(Some)
        },
    )
}

fn value_to_micro(value: &Value, key: &str) -> Result<u128> {
    match value {
        Value::Number(number) => number
            .as_u64()
            .map(u128::from)
            .ok_or_else(|| eyre!("`{key}` must fit into u64 micro XOR range")),
        Value::String(text) => text
            .parse::<u128>()
            .wrap_err_with(|| format!("failed to parse `{key}` as an unsigned integer")),
        _ => Err(eyre!(
            "`{key}` must be encoded as a JSON number or string (micro XOR)"
        )),
    }
}

fn build_reserve_ledger_plan(
    quote_path: &Path,
    projection: LedgerProjectionAmounts,
    provider: &AccountId,
    treasury: &AccountId,
    reserve: &AccountId,
    asset_definition: &AssetDefinitionId,
) -> Result<Value> {
    let mut instructions = Vec::new();
    append_transfer_instruction(
        &mut instructions,
        provider,
        treasury,
        projection.rent_due,
        asset_definition,
    )?;
    append_transfer_instruction(
        &mut instructions,
        provider,
        reserve,
        projection.reserve_shortfall,
        asset_definition,
    )?;

    let mut root = Map::new();
    root.insert(
        "quote_path".into(),
        Value::from(quote_path.display().to_string()),
    );
    root.insert(
        "rent_due_micro_xor".into(),
        ledger_micro_value(projection.rent_due),
    );
    root.insert(
        "reserve_shortfall_micro_xor".into(),
        ledger_micro_value(projection.reserve_shortfall),
    );
    root.insert(
        "top_up_shortfall_micro_xor".into(),
        ledger_micro_value(projection.top_up_shortfall),
    );
    root.insert("instructions".into(), Value::Array(instructions));
    Ok(Value::Object(root))
}

fn build_reserve_lifecycle_value(
    quote_path: &Path,
    lifecycle: &ReserveLifecycleProjection,
) -> Result<Value> {
    let mut root = Map::new();
    root.insert(
        "quote_path".into(),
        Value::from(quote_path.display().to_string()),
    );
    root.insert(
        "stage".into(),
        Value::from(reserve_lifecycle_stage_label(lifecycle.stage)),
    );
    root.insert(
        "days_past_due".into(),
        Value::Number(Number::from(u64::from(lifecycle.days_past_due))),
    );
    root.insert(
        "grace_period_days".into(),
        Value::Number(Number::from(u64::from(lifecycle.grace_period_days))),
    );
    root.insert(
        "default_after_days".into(),
        Value::Number(Number::from(u64::from(lifecycle.default_after_days))),
    );
    root.insert(
        "rent_due_micro_xor".into(),
        ledger_micro_value(lifecycle.rent_due),
    );
    root.insert(
        "reserve_shortfall_micro_xor".into(),
        ledger_micro_value(lifecycle.reserve_shortfall),
    );
    root.insert(
        "top_up_shortfall_micro_xor".into(),
        ledger_micro_value(lifecycle.top_up_shortfall),
    );
    root.insert(
        "credit_draw_micro_xor".into(),
        ledger_micro_value(lifecycle.credit_draw),
    );
    let available = lifecycle
        .credit_available_after_draw
        .map_or(Value::Null, ledger_micro_value);
    root.insert("credit_available_after_draw_micro_xor".into(), available);
    root.insert(
        "credit_shortfall_micro_xor".into(),
        ledger_micro_value(lifecycle.credit_shortfall),
    );
    root.insert(
        "accrued_interest_micro_xor".into(),
        ledger_micro_value(lifecycle.accrued_interest),
    );
    root.insert(
        "total_due_after_credit_micro_xor".into(),
        ledger_micro_value(lifecycle.total_due_after_credit),
    );
    root.insert(
        "restrict_new_manifests".into(),
        Value::from(lifecycle.restrict_new_manifests),
    );
    root.insert(
        "disable_adverts".into(),
        Value::from(lifecycle.disable_adverts),
    );
    root.insert(
        "requires_governance_notification".into(),
        Value::from(lifecycle.requires_governance_notification),
    );
    root.insert(
        "requires_manual_credit_approval".into(),
        Value::from(lifecycle.requires_manual_credit_approval),
    );
    let projection = norito::json::to_value(lifecycle)
        .wrap_err("failed to serialize reserve lifecycle projection")?;
    root.insert("lifecycle_projection".into(), projection);
    Ok(Value::Object(root))
}

fn append_transfer_instruction(
    instructions: &mut Vec<Value>,
    source_account: &AccountId,
    destination_account: &AccountId,
    amount: XorAmount,
    asset_definition: &AssetDefinitionId,
) -> Result<()> {
    if amount.is_zero() {
        return Ok(());
    }
    let numeric_amount = xor_amount_to_numeric(amount)?;
    let asset_id = AssetId::new(asset_definition.clone(), source_account.clone());
    let transfer = InstructionBox::from(Transfer::asset_numeric(
        asset_id,
        numeric_amount,
        destination_account.clone(),
    ));
    let value = norito::json::to_value(&transfer)
        .wrap_err("failed to serialize reserve ledger transfer instruction")?;
    instructions.push(value);
    Ok(())
}

fn xor_amount_to_numeric(amount: XorAmount) -> Result<Numeric> {
    Numeric::try_new(amount.as_micro(), 6)
        .map_err(|err| eyre!("failed to convert XOR amount to Numeric: {err}"))
}

fn ledger_micro_value(amount: XorAmount) -> Value {
    let micro = amount.as_micro();
    u64::try_from(micro).map_or_else(
        |_| Value::String(micro.to_string()),
        |value| Value::Number(Number::from(value)),
    )
}

const fn storage_class_label(class: StorageClass) -> &'static str {
    match class {
        StorageClass::Hot => "hot",
        StorageClass::Warm => "warm",
        StorageClass::Cold => "cold",
    }
}

const fn reserve_tier_label(tier: ReserveTier) -> &'static str {
    match tier {
        ReserveTier::TierA => "tier-a",
        ReserveTier::TierB => "tier-b",
        ReserveTier::TierC => "tier-c",
    }
}

const fn reserve_duration_label(duration: ReserveDuration) -> &'static str {
    match duration {
        ReserveDuration::Monthly => "monthly",
        ReserveDuration::Quarterly => "quarterly",
        ReserveDuration::Annual => "annual",
    }
}

const fn reserve_lifecycle_stage_label(stage: ReserveLifecycleStage) -> &'static str {
    match stage {
        ReserveLifecycleStage::Active => "active",
        ReserveLifecycleStage::Warning => "warning",
        ReserveLifecycleStage::Grace => "grace",
        ReserveLifecycleStage::Delinquent => "delinquent",
        ReserveLifecycleStage::Default => "default",
    }
}

